@Slf4j
@PluginDescriptor(
	name = "Gauntlet Map"
)
@Getter
public class GauntletMapPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private GauntletMapPanel panel;

	@Inject
	private GauntletMapConfig config;

	@Inject
	private GauntletMapSession session;

	@Inject
	private GauntletMapOverlay mapOverlay;

	@Inject
	private DemiBossRoomOutline demiBossRoomOutline;

	@Inject
	private ClientThread clientThread;

	private Map<Integer, String> fileNameMap = new HashMap<>();

	private Map<Integer, List<Integer>> connectedRoomsMap =  new HashMap<>();

	private NavigationButton navButton;

	private boolean isPanelDisplayed;

    @Getter
    private boolean playerInGauntlet = false;

	@Override
	protected void startUp() throws Exception
	{
		this.panel = injector.getInstance(GauntletMapPanel.class);

		BufferedImage icon = ImageUtil.loadImageResource(GauntletMapPlugin.class, "icon.png");

		navButton = NavigationButton.builder()
			.tooltip("Gauntlet Map")
			.icon(icon)
			.priority(99)
			.panel(panel)
			.build();

		updatePanelDisplay();
		createRequiredMapsAndLists();

		overlayManager.add(mapOverlay);
		overlayManager.add(demiBossRoomOutline);
	}

	@Override
	protected void shutDown() throws Exception
	{
		clientToolbar.removeNavigation(navButton);
		overlayManager.remove(demiBossRoomOutline);
		overlayManager.remove(mapOverlay);
	}

	@Subscribe
	public void onNpcSpawned(NpcSpawned npcSpawned)
	{

        switch (Objects.requireNonNull(npcSpawned.getNpc().getName()).toLowerCase())
        {

            case "crystalline hunllef":
            case "corrupted hunllef":

                if (session.isNewSession())
                {
                    gauntletStarted();
                    playerInGauntlet = true;
                    session.setNewSession(false);
                }

                break;

            case "crystalline bear":
            case "corrupted bear":
            case "crystalline dark beast":
            case "corrupted dark beast":
            case "crystalline dragon":
            case "corrupted dragon":

                //Check if the npc has spawned before

                GauntletMapConstants.DEMI_ROOM_LIST.forEach(room ->
                {

                    if (session.getRoomTilesMap().get(room).contains(npcSpawned.getNpc().getWorldLocation()))
                    {

                        if (!session.getDemiBossLocationsMap().containsKey(room))
                        {

                            switch (Objects.requireNonNull(npcSpawned.getNpc().getName()).toLowerCase()) {

                                case "crystalline bear":
                                case "corrupted bear":

                                    session.getDemiBossLocationsMap().put(session.getActivatedRoom(), GauntletMapConstants.MapIcons.DEMIBOSS_MELEE);
                                    session.updateGauntletMap(session.getActivatedRoom(), GauntletMapConstants.MapIcons.DEMIBOSS_MELEE);

                                    break;

                                case "crystalline dark beast":
                                case "corrupted dark beast":

                                    session.getDemiBossLocationsMap().put(session.getActivatedRoom(), GauntletMapConstants.MapIcons.DEMIBOSS_RANGED);
                                    session.updateGauntletMap(session.getActivatedRoom(), GauntletMapConstants.MapIcons.DEMIBOSS_RANGED);

                                    break;

                                case "crystalline dragon":
                                case "corrupted dragon":

                                    session.getDemiBossLocationsMap().put(session.getActivatedRoom(), GauntletMapConstants.MapIcons.DEMIBOSS_MAGIC);
                                    session.updateGauntletMap(session.getActivatedRoom(), GauntletMapConstants.MapIcons.DEMIBOSS_MAGIC);

                                    break;

                            }
                        }
                    }
                });

                break;

        }

	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned npcDespawned)
	{
		if (!playerInGauntlet)
        {
            return;
        }

        switch (Objects.requireNonNull(npcDespawned.getNpc().getName()).toLowerCase())
        {

            case "crystalline bear":
            case "corrupted bear":
            case "crystalline dark beast":
            case "corrupted dark beast":
            case "crystalline dragon":
            case "corrupted dragon":

                NPC demiBoss = npcDespawned.getNpc();
                WorldPoint player = client.getLocalPlayer().getWorldLocation();
                int room = 0;

                if (demiBoss.isDead())
                {

                    for (Map.Entry<Integer, GauntletMapConstants.MapIcons> demiLocation : session.getDemiBossLocationsMap().entrySet())
                    {

                        if (session.getRoomTilesMap().get(demiLocation.getKey()).contains(demiBoss.getWorldLocation()))
                        {
                            room = demiLocation.getKey();
                            session.getDemiBossLocationsMap().remove(room);
                        }

                    }

                    if (session.getRoomTilesMap().get(room).contains(player))
                    {
                        session.updateGauntletMap(room, GauntletMapConstants.MapIcons.PLAYER);
                    }

                    else if (session.getRoomResourcesMap().get(room) != null)
                    {
                        session.updateRoomResources(room);
                    }

                    else
                    {
                        session.updateGauntletMap(room, GauntletMapConstants.MapIcons.ACTIVE_TILE);
                    }

                }

                break;
        }

	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged gameStateChanged)
    {

        switch (gameStateChanged.getGameState())
        {

            case LOADING:

                if (!playerInGauntlet)
                {
                    return;
                }

                //Clear when room is activated to prevent duplicate loading
                session.getHighlightNodeMap().clear();

                session.updateGauntletMap(session.getActivatedRoom(), GauntletMapConstants.MapIcons.ACTIVE_TILE);

                break;

            case LOGIN_SCREEN:
                panel.clearPanel();
                break;

        }

    }

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{

		if (!event.getGroup().equals("Gauntlet Map"))
		{
			return;
		}

        switch (event.getKey())
        {
            case "panelVisibility":

                updatePanelDisplay();
                break;

            case "showGrymLeaves":
            case "showFishingSpots":

                for (Map.Entry<Integer, List<Integer>> resourceList : session.getRoomResourcesMap().entrySet())
                {
                    session.updateRoomResources(resourceList.getKey());
                }

                break;
        }

		if (event.getKey().equals("panelVisibility"))
		{
			updatePanelDisplay();
		}

	}

	@Subscribe
	public void onGameTick(GameTick gameTick)
	{

		updatePanelDisplay();

        if (!playerInGauntlet)
        {
            return;
        }

		session.updateCurrentRoom(client.getLocalPlayer().getWorldLocation());

	}

	@Subscribe
	public void onGameObjectSpawned(GameObjectSpawned gameObjectSpawned)
	{

		if (!playerInGauntlet)
        {
            return;
        }

        WorldPoint player = client.getLocalPlayer().getWorldLocation();
        GameObject gameObject = gameObjectSpawned.getGameObject();

        switch (gameObject.getId())
        {

            case ObjectID.GAUNTLET_POND:
            case ObjectID.GAUNTLET_POND_HM:
            case ObjectID.GAUNTLET_HERB:
            case ObjectID.GAUNTLET_HERB_HM:

                if (session.getRoomTilesMap().get(session.getActivatedRoom()).contains(gameObject.getWorldLocation()))
                {
                    if (session.getRoomResourcesMap().containsKey(session.getActivatedRoom()))
                    {
                        session.getRoomResourcesMap().get(session.getActivatedRoom()).add(gameObject.getId());
                    }
                    else
                    {
                        session.getRoomResourcesMap().put(session.getActivatedRoom(), Lists.newArrayList(gameObject.getId()));
                    }
                    session.updateRoomResources(session.getActivatedRoom());
                }

                break;

            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_01_HM:
            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_02_HM:
            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_01:
            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_02:

                session.getDemiBossNodeLocationsMap().forEach((roomKey, worldPoints) ->
                {

                    if (worldPoints.contains(gameObject.getWorldLocation()))
                    {
                        if (session.getHighlightNodeMap().containsKey(roomKey))
                        {
                            session.getHighlightNodeMap().get(roomKey).add(gameObject);
                        }
                        else
                        {
                            session.getHighlightNodeMap().put(roomKey, Lists.newArrayList(gameObject));
                        }
                    }

                });
                break;
        }

	}

	@Subscribe
	public void onGameObjectDespawned(GameObjectDespawned gameObjectDespawned)
	{
		if (!playerInGauntlet)
        {
            return;
        }

        GameObject gameObject = gameObjectDespawned.getGameObject();

        switch (gameObject.getId())
        {

            case ObjectID.GAUNTLET_POND:
            case ObjectID.GAUNTLET_POND_HM:
            case ObjectID.GAUNTLET_HERB:
            case ObjectID.GAUNTLET_HERB_HM:

                if (session.getRoomTilesMap().get(session.getCurrentRoom()).contains(gameObject.getWorldLocation()))
                {

                    for (Integer resource : session.getRoomResourcesMap().get(session.getCurrentRoom()))
                    {

                        if (gameObject.getId() == resource)
                        {
                            session.getRoomResourcesMap().get(session.getCurrentRoom()).remove(resource);
                            return;
                        }

                    }

                }

                break;

            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_01_HM:
            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_02_HM:
            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_01:
            case ObjectID.PRIF_GAUNTLET_DOOR_WALL_UNLIT_02:

                session.getDemiBossNodeLocationsMap().forEach((roomKey, worldPoints) ->
                {

                    worldPoints.removeIf(wp -> wp.equals(gameObject.getWorldLocation()));

                    if (session.getHighlightNodeMap().containsKey(roomKey))
                    {
                        session.getHighlightNodeMap().get(roomKey).removeIf(wp -> wp.getWorldLocation().equals(gameObject.getWorldLocation()));
                    }

                });

                break;

        }

	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged event)
	{

        switch (event.getVarbitId())
        {

            case VarbitID.PLAYER_IN_GAUNTLET:
                if (event.getValue() == 0)
                {
                    playerInGauntlet = false;
                    session.clear();
                }
                break;

            case VarbitID.GAUNTLET_START:
                if (event.getValue() != 0)
                {

                    session.setStartLocation(event.getValue() + 1);
                    session.setCurrentRoom(session.getStartLocation());

                }
                break;

            case VarbitID.GAUNTLET_CORRUPTED:
                session.setCorrupted(event.getValue() == 1);
                break;

            case VarbitID.GAUNTLET_BOSS_STARTED:
                if (event.getValue() == 1)
                {
                    session.clear();
                }
                break;

        }

        if (playerInGauntlet)
        {
            session.setActivatedRoom(GauntletMapConstants.ROOM_FOUND_VARBIT_MAP.get(event.getVarbitId()));
        }

	}

	private void createRequiredMapsAndLists()
	{

		for (int room = 1; room <= 49; room++)
		{

            List<Integer> connectedRoomsList = new ArrayList<>();

			switch (room)
			{

				case 1:
					connectedRoomsList.addAll(Arrays.asList(2, 8));
					fileNameMap.put(room, "_bottom_left.png");
					break;

				case 7:
					connectedRoomsList.addAll(Arrays.asList(6, 14));
					fileNameMap.put(room, "_bottom_right.png");
					break;

				case 43:
					connectedRoomsList.addAll(Arrays.asList(36, 44));
					fileNameMap.put(room, "_top_left.png");
					break;

				case 49:
					connectedRoomsList.addAll(Arrays.asList(42, 48));
					fileNameMap.put(room, "_top_right.png");
					break;

				case 8:
				case 15:
				case 22:
				case 29:
				case 36:
					connectedRoomsList.addAll(Arrays.asList(room - 7, room + 1, room + 7));
					fileNameMap.put(room, "_left.png");
					break;

				case 14:
				case 21:
				case 28:
				case 35:
				case 42:
					connectedRoomsList.addAll(Arrays.asList(room - 7, room - 1, room + 7));
					fileNameMap.put(room, "_right.png");
					break;

				case 2:
				case 3:
				case 4:
				case 5:
				case 6:
					connectedRoomsList.addAll(Arrays.asList(room - 1, room + 1, room + 7));
					fileNameMap.put(room, "_bottom.png");
					break;

				case 44:
				case 45:
				case 46:
				case 47:
				case 48:
					connectedRoomsList.addAll(Arrays.asList(room - 7, room - 1, room + 1));
					fileNameMap.put(room, "_top.png");
					break;

				default:
					connectedRoomsList.addAll(Arrays.asList(room - 7, room - 1, room + 1, room + 7));
					fileNameMap.put(room, ".png");
					break;

			}

			connectedRoomsMap.put(room, connectedRoomsList);

		}
	}

    private void gauntletStarted()
    {

        session.createInstanceMaps(client.getLocalPlayer().getWorldLocation());

        session.updateGauntletMap(session.getStartLocation(), GauntletMapConstants.MapIcons.PLAYER);
        session.updateGauntletMap(GauntletMapSession.BOSS_ROOM, GauntletMapConstants.MapIcons.BOSS);

        if (config.showDemiBosses())
        {
            List<Integer> demiList = GauntletMapConstants.DEMI_ROOM_LIST;

            if (config.showOnlyGuaranteedDemiBosses())
            {
                demiList = GauntletMapConstants.GUARANTEED_DEMI_ROOM_LIST;
            }

            demiList.forEach(room -> {session.updateGauntletMap(room, GauntletMapConstants.MapIcons.DEMIBOSS_UNKNOWN);});

        }

        //Start the map in the sidebar
        panel.firstLoad();

    }

	private boolean shouldDisplayPanel()
    {

		switch (config.panelVisibility())
		{

			case NEVER:
				return false;

			case IN_GAUNTLET:
				return playerInGauntlet;

			case ALWAYS:
			default:
				return true;

		}

	}

	private void updatePanelDisplay()
	{
		boolean shouldDisplayPanel = shouldDisplayPanel();
		if (shouldDisplayPanel == isPanelDisplayed)
		{
			return;
		}

		if (shouldDisplayPanel)
		{
			isPanelDisplayed = true;
			clientToolbar.addNavigation(navButton);
		}
		else
		{
			isPanelDisplayed = false;
			clientToolbar.removeNavigation(navButton);
		}
	}

	@Provides
    GauntletMapConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(GauntletMapConfig.class);
	}
}

package com.gauntletmap;

import com.google.common.collect.Lists;
import lombok.Getter;
import lombok.Setter;
import net.runelite.api.GameObject;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ObjectID;
import net.runelite.client.util.ImageUtil;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;

@Singleton
public class GauntletMapSession
{
	private final GauntletMapPlugin plugin;

	private final GauntletMapConfig config;

	private static final int TILE_DISTANCE = 16;

	static final int BOSS_ROOM = 25;

    @Getter
	private Map<Integer, GauntletMapConstants.MapIcons> demiBossLocationsMap = new TreeMap<>();

	@Getter
	private Map<Integer, List<GameObject>> highlightNodeMap = new TreeMap<>();

    @Getter
	private Map<Integer, List<WorldPoint>> demiBossNodeLocationsMap = new TreeMap<>();

    @Getter
	private Map<Integer, List<Integer>> roomResourcesMap = new TreeMap<>();

	@Getter
	private Map<Integer, BufferedImage> gauntletMap;

    @Getter
	private Map<Integer, List<WorldPoint>> roomTilesMap;

    @Getter
	@Setter
    private Integer startLocation;


    @Setter
	private boolean corrupted = false;

    @Getter
    @Setter
    private boolean newSession = true;

    @Getter
    @Setter
    private Integer currentRoom;

    @Getter
    @Setter
    private Integer activatedRoom;

	@Inject
	GauntletMapSession(GauntletMapPlugin plugin, GauntletMapConfig config)
	{
		this.plugin = plugin;
		this.config = config;
	}

	public void clear()
	{
		corrupted = false;
		currentRoom = null;
        newSession = true;
		highlightNodeMap.clear();
		demiBossLocationsMap.clear();
		roomResourcesMap.clear();
        gauntletMap.clear();
		plugin.getPanel().clearPanel();
	}

	public void createInstanceMaps(WorldPoint playerLocation)
	{
		WorldPoint northWestCornerRoom = null;
		Map<Integer, List<WorldPoint>> roomTilesMap = new TreeMap<>();
		Map<Integer, BufferedImage> gauntletMap = new TreeMap<>();

		switch (startLocation)
		{
			//North start
			case 32:
				northWestCornerRoom = calculateNewPoint(playerLocation, -3, 2, -3, -2);
				break;

			//East start
			case 26:
				northWestCornerRoom = calculateNewPoint(playerLocation, -4, 3, -3, -2);
				break;

			//South start
			case 18:
				northWestCornerRoom = calculateNewPoint(playerLocation, -3, 4, -3, -2);
				break;

			//West start
			case 24:
				northWestCornerRoom = calculateNewPoint(playerLocation, -2, 3, -3, -2);
				break;
		}

		for (int gauntletMapYAxis = 6; gauntletMapYAxis >= 0; gauntletMapYAxis--)
		{
			for (int gauntletMapXAxis = 0; gauntletMapXAxis <= 6; gauntletMapXAxis++)
			{
				WorldPoint middleOfRoom = calculateNewPoint(northWestCornerRoom, gauntletMapXAxis, gauntletMapYAxis - 6, 0, 0);
				WorldPoint northWestCornerTile = calculateNewPoint(middleOfRoom, 0, 0, -6, 5);

                List<WorldPoint> roomTiles = new ArrayList<>();
				int room = (gauntletMapYAxis * 7 + gauntletMapXAxis + 1);

				String path = "inactive" + plugin.getFileNameMap().get(room);
				gauntletMap.put(room, ImageUtil.loadImageResource(GauntletMapPlugin.class, path));

				if (!plugin.getConnectedRoomsMap().get(room).contains(startLocation))
				{
					plugin.getConnectedRoomsMap().get(room).add(startLocation);
				}

				for (int roomY = 0; roomY <= 11; roomY++)
				{
					for (int roomX = 0; roomX <= 11; roomX++)
					{
						roomTiles.add(calculateNewPoint(northWestCornerTile, 0, 0, roomX, -roomY));
					}
				}

				for (int roomEntranceY = 0; roomEntranceY <= 1; roomEntranceY++)
				{
					for (int roomEntranceX = 0; roomEntranceX <= 1; roomEntranceX++)
					{
						roomTiles.add(calculateNewPoint(middleOfRoom, 0, 0, -roomEntranceX, 7 - roomEntranceY));
						roomTiles.add(calculateNewPoint(middleOfRoom, 0, 0, 7 - roomEntranceX, -roomEntranceY));
						roomTiles.add(calculateNewPoint(middleOfRoom, 0, 0, -roomEntranceX, -7 - roomEntranceY));
						roomTiles.add(calculateNewPoint(middleOfRoom, 0, 0, -7 - roomEntranceX, -roomEntranceY));
					}
				}

				for (Integer connectedRoom : plugin.getConnectedRoomsMap().get(room))
				{

                    List<Integer> demiList = GauntletMapConstants.DEMI_ROOM_LIST;

                    if (config.showOnlyGuaranteedDemiBosses()) {
                        demiList = GauntletMapConstants.GUARANTEED_DEMI_ROOM_LIST;
                    }

					if (demiList.contains(connectedRoom))
					{
						switch (connectedRoom - room)
						{
							case 7:
								//North
								if (demiBossNodeLocationsMap.containsKey(room))
								{
									demiBossNodeLocationsMap.get(room).addAll(Lists.newArrayList(
											calculateNewPoint(middleOfRoom, 0, 0, -2, 7),
											calculateNewPoint(middleOfRoom, 0, 0, -2, 6),
											calculateNewPoint(middleOfRoom, 0, 0, 1, 7),
											calculateNewPoint(middleOfRoom, 0, 0, 1, 6)
									));
								}
								else
								{
									demiBossNodeLocationsMap.put(
											room,
											Lists.newArrayList(
													calculateNewPoint(middleOfRoom, 0, 0, -2, 7),
													calculateNewPoint(middleOfRoom, 0, 0, -2, 6),
													calculateNewPoint(middleOfRoom, 0, 0, 1, 7),
													calculateNewPoint(middleOfRoom, 0, 0, 1, 6)
											));
								}
								break;

							case -7:
								//South
								if (demiBossNodeLocationsMap.containsKey(room))
								{
									demiBossNodeLocationsMap.get(room).addAll(Lists.newArrayList(
											calculateNewPoint(middleOfRoom, 0, 0, -2, -7),
											calculateNewPoint(middleOfRoom, 0, 0, -2, -8),
											calculateNewPoint(middleOfRoom, 0, 0, 1, -7),
											calculateNewPoint(middleOfRoom, 0, 0, 1, -8)
									));
								}
								else
								{
									demiBossNodeLocationsMap.put(
											room,
											Lists.newArrayList(
													calculateNewPoint(middleOfRoom, 0, 0, -2, -7),
													calculateNewPoint(middleOfRoom, 0, 0, -2, -8),
													calculateNewPoint(middleOfRoom, 0, 0, 1, -7),
													calculateNewPoint(middleOfRoom, 0, 0, 1, -8)
											));
								}
								break;

							case 1:
								//East
								if (demiBossNodeLocationsMap.containsKey(room))
								{
									demiBossNodeLocationsMap.get(room).addAll(Lists.newArrayList(
											calculateNewPoint(middleOfRoom, 0, 0, 7, 1),
											calculateNewPoint(middleOfRoom, 0, 0, 6, 1),
											calculateNewPoint(middleOfRoom, 0, 0, 7, -2),
											calculateNewPoint(middleOfRoom, 0, 0, 6, -2)
									));
								}
								else
								{
									demiBossNodeLocationsMap.put(
											room,
											Lists.newArrayList(
													calculateNewPoint(middleOfRoom, 0, 0, 7, 1),
													calculateNewPoint(middleOfRoom, 0, 0, 6, 1),
													calculateNewPoint(middleOfRoom, 0, 0, 7, -2),
													calculateNewPoint(middleOfRoom, 0, 0, 6, -2)
											));
								}
								break;

							case -1:
								//West
								if (demiBossNodeLocationsMap.containsKey(room))
								{
									demiBossNodeLocationsMap.get(room).addAll(Lists.newArrayList(
											calculateNewPoint(middleOfRoom, 0, 0, -7, 1),
											calculateNewPoint(middleOfRoom, 0, 0, -8, 1),
											calculateNewPoint(middleOfRoom, 0, 0, -7, -2),
											calculateNewPoint(middleOfRoom, 0, 0, -8, -2)
									));
								}
								else
								{
									demiBossNodeLocationsMap.put(
											room,
											Lists.newArrayList(
													calculateNewPoint(middleOfRoom, 0, 0, -7, 1),
													calculateNewPoint(middleOfRoom, 0, 0, -8, 1),
													calculateNewPoint(middleOfRoom, 0, 0, -7, -2),
													calculateNewPoint(middleOfRoom, 0, 0, -8, -2)
											));
								}
								break;
						}
					}
				}

				roomTilesMap.put(room, roomTiles);

			}
		}

		this.gauntletMap = gauntletMap;
		this.roomTilesMap = roomTilesMap;
	}

	private WorldPoint calculateNewPoint(WorldPoint startPoint, Integer roomsX, Integer roomsY, Integer tilesX, Integer tilesY)
	{

		return new WorldPoint
			(
				startPoint.getX() + (roomsX * TILE_DISTANCE) + tilesX,
				startPoint.getY() + (roomsY * TILE_DISTANCE) + tilesY,
				startPoint.getPlane()
			);

	}

	public void updateCurrentRoom(WorldPoint playerLocation)
	{

		//If player hasn't left the room
		if (roomTilesMap.get(currentRoom).contains(playerLocation))
		{
			return;
		}

		//Next room can only be connected to previous room -- Check connected rooms
		plugin.getConnectedRoomsMap().get(currentRoom).forEach(connectedRoom ->
		{

			if (roomTilesMap.get(connectedRoom).contains(playerLocation))
			{
				int previousRoom = currentRoom;
				setCurrentRoom(connectedRoom);

				if (demiBossLocationsMap.containsKey(previousRoom))
				{
					updateGauntletMap(previousRoom, demiBossLocationsMap.get(previousRoom));
				}
				else if (roomResourcesMap.containsKey(previousRoom))
				{
					updateRoomResources(previousRoom);
				}
				else
				{
					updateGauntletMap(previousRoom, GauntletMapConstants.MapIcons.ACTIVE_TILE);
				}

				updateGauntletMap(currentRoom, GauntletMapConstants.MapIcons.PLAYER);
			}

		});

	}

    void updateRoomResources(Integer room)
	{

		if (demiBossLocationsMap.containsKey(room))
		{
			return;
		}

        int pond = ObjectID.GAUNTLET_POND;
        int pondCG = ObjectID.GAUNTLET_POND_HM;
        int herb = ObjectID.GAUNTLET_HERB;
        int herbCG = ObjectID.GAUNTLET_HERB_HM;

        if ((roomResourcesMap.get(room).contains(pond) || roomResourcesMap.get(room).contains(pondCG)) &&
            (roomResourcesMap.get(room).contains(herb) || roomResourcesMap.get(room).contains(herbCG)) &&
            config.showFishingSpots() &&
            config.showGrymLeaves())
        {
            updateGauntletMap(room, GauntletMapConstants.MapIcons.FISHING_SPOT_GRYM_ROOT);
        }

        else if (roomResourcesMap.get(room).contains(pond) || roomResourcesMap.get(room).contains(pondCG) && config.showFishingSpots())
        {
            updateGauntletMap(room, GauntletMapConstants.MapIcons.FISHING_SPOT);
        }

        else if (roomResourcesMap.get(room).contains(herb) ||  roomResourcesMap.get(room).contains(herbCG) && config.showGrymLeaves())
        {
            updateGauntletMap(room, GauntletMapConstants.MapIcons.GRYM_ROOT);
        }

        else
        {
            updateGauntletMap(room, GauntletMapConstants.MapIcons.ACTIVE_TILE);
        }

	}

	public void updateGauntletMap(Integer room, GauntletMapConstants.MapIcons icon)
	{

		String path;
		String type = "regular/";

		if (corrupted)
		{
			type = "corrupted/";
		}

		switch (icon)
		{

			case PLAYER:
				path = type + icon + plugin.getFileNameMap().get(room);
				if (room == startLocation)
				{
					path = type + "player_start.png";
				}
				gauntletMap.put(room, ImageUtil.loadImageResource(GauntletMapPlugin.class, path));
				break;

            case ACTIVE_TILE:
                path = icon + plugin.getFileNameMap().get(room);
                if (room == startLocation)
                {
                    path = type + "start_room.png";
                }
                gauntletMap.put(room, ImageUtil.loadImageResource(GauntletMapPlugin.class, path));
                break;

			case BOSS:
            case DEMIBOSS_UNKNOWN:
				path = type + icon + plugin.getFileNameMap().get(room);
				gauntletMap.put(room, ImageUtil.loadImageResource(GauntletMapPlugin.class, path));
				break;

            case DEMIBOSS_MELEE:
			case DEMIBOSS_MAGIC:
            case DEMIBOSS_RANGED:
            case FISHING_SPOT:
            case GRYM_ROOT:
            case FISHING_SPOT_GRYM_ROOT:
                path = icon + plugin.getFileNameMap().get(room);
				gauntletMap.put(room, ImageUtil.loadImageResource(GauntletMapPlugin.class, path));
				break;

        }

        plugin.getPanel().updatePanel(room);

    }

	public BufferedImage scaleImage(Integer size, BufferedImage image)
	{
		if (size == 34)
		{
			return image;
		}

		Image scaledImage = image.getScaledInstance(size, size, Image.SCALE_DEFAULT);
		BufferedImage bufferedImage = new BufferedImage(scaledImage.getWidth(null), scaledImage.getHeight(null), BufferedImage.TYPE_INT_ARGB);
		bufferedImage.getGraphics().drawImage(scaledImage, 0, 0, null);
		return bufferedImage;
	}
}

